import { GetNotes } from "./action";
import { Note } from "./api/route";
import CreateNoteForm from "./createNoteForm";

export default async function Page() {
  
  const notes = await GetNotes()


  return (
    <div>
      <div>
        {notes.map((item: Note) => (
          <p key={item.id}>
            {item.id}: {item.text}
          </p>
        ))}
      </div>



      <div>
        
        <CreateNoteForm/>
      </div>
    </div>
  );
}
